/* Local BroadcastChannel + Storage sync layer alongside MQTT for multi-tab / multi-window reliability */
/* bkBC provided by state.js */
try{
  if(false){
    bkBC=new BroadcastChannel('sharb_bakasa_sync_v1');
    bkBC.onmessage=ev=>{
      const m=ev&&ev.data;
      if(!m||!m.topic)return;
      dispatchNetTopic(m.topic,m.payload);
    };
  }
  window.addEventListener('storage',ev=>{
    if(!ev.key||!ev.newValue)return;
    if(ev.key.startsWith('bk_bus_msg_')){
      try{
        const m=JSON.parse(ev.newValue);
        if(m&&m.topic){
          dispatchNetTopic(m.topic,m.payload);
        }
      }catch(e){}
    }
  });
}catch(e){}

function bkSub(topic,fn){
  sub(topic,fn);
  try{
    const ret=localStorage.getItem('bk_ret_'+topic);
    if(ret){
      const parsed=JSON.parse(ret);
      if(parsed&&parsed.payload)setTimeout(()=>{if(NET.topics.get(topic)===fn){try{fn(parsed.payload,topic)}catch(e){}}},10);
    }
  }catch(e){}
}
function bkUnsub(topic){
  unsub(topic);
}
function bkPubMsg(topic,obj,opt){
  pub(topic,obj,Object.assign({},opt||{},{_skipLocalBus:true}));
  try{
    if(opt&&opt.retain){
      localStorage.setItem('bk_ret_'+topic,JSON.stringify({ts:Date.now(),payload:obj}));
    }
    if(bkBC)bkBC.postMessage({topic,payload:obj,ts:Date.now()});
    localStorage.setItem('bk_bus_msg_'+topic,JSON.stringify({topic,payload:obj,ts:Date.now(),r:Math.random()}));
  }catch(e){}
  const localFn=NET.topics.get(topic);
  if(localFn&&!topic.endsWith('/st')&&!topic.endsWith('/beat')){
    setTimeout(()=>{try{localFn(obj,topic)}catch(e){}},5);
  }
  return true;
}

async function bkKP(){
  let j=null;try{j=JSON.parse(sessionStorage.getItem('bk_kp'))}catch(e){}
  if(j&&j.priv&&j.pub)try{return{priv:await crypto.subtle.importKey('jwk',j.priv,ECP,true,['deriveKey']),pub:j.pub}}catch(e){}
  const k=await crypto.subtle.generateKey(ECP,true,['deriveKey']);
  const priv=await crypto.subtle.exportKey('jwk',k.privateKey),pub=await crypto.subtle.exportKey('jwk',k.publicKey);
  try{sessionStorage.setItem('bk_kp',JSON.stringify({priv,pub}))}catch(e){}
  return{priv:k.privateKey,pub};
}
async function bkDerive(priv,pubJwk){
  const pk=await crypto.subtle.importKey('jwk',pubJwk,ECP,false,[]);
  return crypto.subtle.deriveKey({name:'ECDH',public:pk},priv,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);
}
async function bkEnc(key,o){
  const iv=crypto.getRandomValues(new Uint8Array(12));
  return{iv:b64(iv),ct:b64(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(o))))};
}
async function bkDec(key,m){
  return JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:ub64(m.iv)},key,ub64(m.ct))));
}
const bkNorm=s=>String(s||'').replace(/[ً-ْـ]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/\s+/g,' ').trim();

function bkShuffle(arr){
  const a=arr.slice();
  for(let i=a.length-1;i>0;i--){
    const j=rnd(i+1);
    const t=a[i];a[i]=a[j];a[j]=t;
  }
  return a;
}

function bkWordsTooSimilar(w1,w2){
  const n1=bkNorm(w1), n2=bkNorm(w2);
  if(!n1||!n2)return true;
  if(n1===n2)return true;
  if(n1.includes(n2)||n2.includes(n1)){
    if(Math.min(n1.length,n2.length)>=4)return true;
  }
  const f1=n1.split(' ')[0], f2=n2.split(' ')[0];
  if(f1&&f2&&f1===f2&&f1.length>=3)return true;
  return false;
}

function bkBuild8WordChoices(secretWord,altWord,cat,diff){
  const chosen=[secretWord];
  const canAdd=cand=>{
    if(!cand)return false;
    if(altWord&&bkNorm(cand)===bkNorm(altWord))return false;
    for(const ex of chosen){
      if(bkWordsTooSimilar(cand,ex))return false;
    }
    return true;
  };
  // Tier 1: Same category & same difficulty
  const tier1=bkShuffle(BK_WORD_DB.filter(x=>x.cat===cat&&( !diff||diff==='الكل'||x.diff===diff )).map(x=>x.w));
  for(const w of tier1){
    if(chosen.length>=8)break;
    if(canAdd(w))chosen.push(w);
  }
  // Tier 2: Same category, any difficulty
  if(chosen.length<8){
    const tier2=bkShuffle(BK_WORD_DB.filter(x=>x.cat===cat).map(x=>x.w));
    for(const w of tier2){
      if(chosen.length>=8)break;
      if(canAdd(w))chosen.push(w);
    }
  }
  // Tier 3: Same category relaxed similarity (still strictly unique normalized)
  if(chosen.length<8){
    const tier2b=bkShuffle(BK_WORD_DB.filter(x=>x.cat===cat).map(x=>x.w));
    for(const w of tier2b){
      if(chosen.length>=8)break;
      const nw=bkNorm(w);
      if(nw&&(!altWord||nw!==bkNorm(altWord))&&!chosen.some(c=>bkNorm(c)===nw))chosen.push(w);
    }
  }
  // Tier 4: Global pool fallback if a custom category has < 8 words
  if(chosen.length<8){
    const tier3=bkShuffle(BK_WORD_DB.map(x=>x.w));
    for(const w of tier3){
      if(chosen.length>=8)break;
      const nw=bkNorm(w);
      if(nw&&(!altWord||nw!==bkNorm(altWord))&&!chosen.some(c=>bkNorm(c)===nw))chosen.push(w);
    }
  }
  return bkShuffle(chosen.slice(0,8));
}
window.bkBuild8WordChoices=bkBuild8WordChoices;

function bkSaveSession(){
  try{
    if(!BK.code){
      sessionStorage.removeItem('bk_session');
      sessionStorage.removeItem('bk_host_state');
      return;
    }
    sessionStorage.setItem('bk_session',JSON.stringify({
      code:BK.code,host:BK.host,my:BK.my,rev:BK.rev,ack:BK.ack,
      selDoubtMode:BK.selDoubtMode,selDoubtTarget:BK.selDoubtTarget,selVote:BK.selVote,
      lastPhaseId:BK.lastPhaseId
    }));
    if(BK.host&&BK.H){
      const H=BK.H;
      const plCopy={};
      Object.keys(H.pl).forEach(k=>{
        const p=H.pl[k];
        plCopy[k]={pid:p.pid,uid:p.uid||String(p.pid).split('.')[0],name:p.name,av:p.av,col:p.col,st:p.st||null,last:p.last,gone:!!p.gone,ready:p.ready!==false,pk:p.pk||null,sent:p.sent||0};
      });
      const serialH=Object.assign({},H,{pl:plCopy});
      sessionStorage.setItem('bk_host_state',JSON.stringify(serialH));
    }
  }catch(e){}
}

async function bkRestoreSession(){
  try{
    const raw=sessionStorage.getItem('bk_session');
    if(!raw)return false;
    const saved=JSON.parse(raw);
    if(!saved||!saved.code)return false;
    if(!BK.kp)BK.kp=await bkKP();
    ensureMQTT().catch(()=>{});
    BK.code=saved.code;
    BK.host=!!saved.host;
    BK.my=saved.my||null;
    BK.rev=!!saved.rev;
    BK.ack=!!saved.ack;
    BK.selDoubtMode=saved.selDoubtMode||'';
    BK.selDoubtTarget=saved.selDoubtTarget||'';
    BK.selVote=saved.selVote||'';
    BK.lastPhaseId=saved.lastPhaseId||'';
    if(BK.host){
      const hRaw=sessionStorage.getItem('bk_host_state');
      if(!hRaw)return false;
      const H=JSON.parse(hRaw);
      for(const pid of Object.keys(H.pl)){
        const p=H.pl[pid];
        if(pid!==ME&&p.pk){
          try{p.key=await bkDerive(BK.kp.priv,p.pk)}catch(e){}
        }
      }
      BK.H=H;
      bkSub(bkT('j'),bkOnJoin);
      bkSub(bkT('up'),bkOnUp);
      bkSub(bkT('bye'),d=>{if(d&&BK.H&&BK.H.pl[d.pid]&&d.pid!==ME){BK.H.pl[d.pid].last=0;bkTick()}});
      clearInterval(BK.iv);BK.iv=setInterval(bkTick,4500);
      bkOpen();
      bkTick();
      return true;
    }else{
      BK.dk=0;BK.sig='';BK.msg='جاري استعادة الاتصال بالغرفة…';
      bkOpen();
      bkSub(bkT('beat'),bkOnBeat);
      return true;
    }
  }catch(e){return false}
}

