const BK_OPT_ICONS={
  'عشوائي':'🎲','أكلات مصرية':'🍲','أكلات عربية وعالمية':'🍕','حلويات':'🍩','مشروبات':'☕',
  'فواكه وخضراوات':'🍉','حيوانات وطيور وكائنات بحرية':'🦁','أشياء منزلية':'🛋️','أدوات وأجهزة':'🛠️',
  'ملابس وإكسسوارات':'🧥','أماكن ومبانٍ':'🏛️','مواصلات':'🚆','مهن':'👨‍⚕️','رياضة وألعاب':'⚽',
  'طبيعة وطقس':'🌋','مدرسة ودراسة':'📚','تقنية وألعاب فيديو':'🎮','أدوات موسيقية وفنون':'🎸',
  'أشياء مصرية ومواقف يومية':'🏮','أدوات ومواقف مضحكة':'😂','أفلام ومسلسلات':'🎬','كورة':'🏆','أمثال شعبية':'📜',
  'blind':'🕵️','alt':'🎭'
};
function bkFmtOpt(c,val,lbl){
  const ic=BK_OPT_ICONS[val]||(c==='nb'?'🕵️':(c==='time'?'⏱️':(c==='max'?'👥':'')));
  return ic?`${ic} ${esc(lbl)}`:esc(lbl);
}
const bkSel=(c,o,v,canEdit)=>{
  const cur=o.find(x=>String(x[0])===String(v))||o[0];
  return `<div class="csel-wrap" data-csel="${esc(c)}">
    <select class="csel-native" data-c="${c}" ${canEdit?'':'disabled'}>
      ${o.map(x=>`<option value="${esc(x[0])}" ${String(x[0])===String(v)?'selected':''}>${esc(x[1])}</option>`).join('')}
    </select>
    <button type="button" class="csel-btn ${canEdit?'':'disabled'}" data-csel-btn="${esc(c)}" ${canEdit?'':'disabled'}>
      <span class="csel-lbl">${bkFmtOpt(c,cur[0],cur[1])}</span>
      <span class="csel-arr">▾</span>
    </button>
    <div class="csel-menu">
      ${o.map(x=>{
        const isOn=String(x[0])===String(v);
        return `<div class="csel-opt ${isOn?'on':''}" data-csel-val="${esc(x[0])}">
          <span>${bkFmtOpt(c,x[0],x[1])}</span>
          <span class="chk">✓</span>
        </div>`;
      }).join('')}
    </div>
  </div>`;
};

function enhanceAllSelects(){
  $$('select:not(.csel-native)').forEach(sel=>{
    if(sel.closest('.csel-wrap'))return;
    const wrap=document.createElement('div');
    wrap.className='csel-wrap';
    sel.parentNode.insertBefore(wrap,sel);
    wrap.appendChild(sel);
    sel.classList.add('csel-native');
    const btn=document.createElement('button');
    btn.type='button';
    btn.className='csel-btn'+(sel.disabled?' disabled':'');
    const menu=document.createElement('div');
    menu.className='csel-menu';
    wrap.appendChild(btn);
    wrap.appendChild(menu);

    const syncUI=()=>{
      const opts=[...sel.options];
      const cur=opts[sel.selectedIndex]||opts[0]||{text:'',value:''};
      btn.disabled=sel.disabled;
      btn.classList.toggle('disabled',sel.disabled);
      btn.innerHTML=`<span class="csel-lbl">🎮 ${esc(cur.text)}</span><span class="csel-arr">▾</span>`;
      menu.innerHTML=opts.map(o=>{
        const on=o.value===sel.value;
        return `<div class="csel-opt ${on?'on':''}" data-csel-val="${esc(o.value)}">
          <span>🎮 ${esc(o.text)}</span>
          <span class="chk">✓</span>
        </div>`;
      }).join('');
    };
    syncUI();
    sel.addEventListener('change',syncUI);
  });
}

document.addEventListener('click',e=>{
  const opt=e.target.closest('.csel-opt');
  if(opt){
    const wrap=opt.closest('.csel-wrap');
    if(!wrap)return;
    const sel=wrap.querySelector('select');
    if(sel&&!sel.disabled){
      const val=opt.getAttribute('data-csel-val');
      sel.value=val;
      wrap.classList.remove('open');
      $$('.csel-opt',wrap).forEach(el=>el.classList.toggle('on',el===opt));
      const lbl=$('.csel-lbl',wrap);
      if(lbl)lbl.innerHTML=opt.querySelector('span').innerHTML;
      sel.dispatchEvent(new Event('change',{bubbles:true}));
      beep(460,.05,'sine',.05);
    }
    return;
  }
  const btn=e.target.closest('.csel-btn');
  if(btn){
    if(btn.disabled||btn.classList.contains('disabled'))return;
    const wrap=btn.closest('.csel-wrap');
    const wasOpen=wrap&&wrap.classList.contains('open');
    $$('.csel-wrap.open').forEach(w=>w.classList.remove('open'));
    if(wrap&&!wasOpen){
      wrap.classList.add('open');
      beep(380,.04,'sine',.04);
    }
    return;
  }
  $$('.csel-wrap.open').forEach(w=>w.classList.remove('open'));
});
const bkName=(S,id)=>{const p=S&&S.pl?S.pl.find(q=>q.pid===id):null;return p?esc(p.name):'—'};
const bkPlayerObj=(S,id)=>(S&&S.pl?S.pl.find(q=>q.pid===id):null)||{name:'—',av:'🙂',col:'#0a84ff'};

